/* 010.Explanation and Warm-up Questions */
stack_include("https://stack.mathedu.jp/sc/tex_library.mac");
/* stack_include("https://stack.mathedu.jp/sc/multilang_library.mac");*/

tex1sig(n):=sconcat(if n<0 then "(" else "", tex1(n), if n<0 then ")" else "");
n0:3;
cL0:random_permutation([1, 1, 2, 2, 3, 4, 5]);
matA0:genmatrix(lambda([i,j], cL0[j]), 1, n0);
matB0:genmatrix(lambda([i,j], cL0[i+3]), n0, 1);
matA0B0S:"\\(";
for k:1 thru n0 do matA0B0S:sconcat(matA0B0S, tex1(matA0[1, k]), "\\times", tex1(matB0[k, 1]), if k<n0 then "+" else "");
matA0B0S:sconcat(matA0B0S, "=");
for k:1 thru n0 do matA0B0S:sconcat(matA0B0S, tex1(matA0[1, k]*matB0[k, 1]), if k<n0 then "+" else "");
matA0B0S:sconcat(matA0B0S, "=");
matA0B0S:sconcat(matA0B0S, tex1(matA0.matB0));
matA0B0S:sconcat(matA0B0S, ".\\)");
/* example 2 */
n1:2;
cL1:random_permutation([1, 1, 2, 3, 4, 5, 6]);
matA1:genmatrix(lambda([i,j], cL1[j]), 1, n1);
matB1:genmatrix(lambda([i,j], cL1[i+n1]), n1, 1);
matA1B1S:"\\(";
for k:1 thru n1 do matA1B1S:sconcat(matA1B1S, tex1sig(matA1[1, k]), "\\times", tex1sig(matB1[k, 1]), if k<n1 then "+" else "");
matA1B1S:sconcat(matA1B1S, "=");
for k:1 thru n1 do matA1B1S:sconcat(matA1B1S, tex1sig(matA1[1, k]*matB1[k, 1]), if k<n1 then "+" else "");
matA1B1S:sconcat(matA1B1S, "=");
matA1B1S:sconcat(matA1B1S, tex1(matA1.matB1));
matA1B1S:sconcat(matA1B1S, ".\\)");
/* simpel questions */
n2:3;
cL2:random_permutation([-2, -1, 1, 2, 3, 4, 5, 6]);
matA2:genmatrix(lambda([i,j], cL2[j]), 1, n2);
matB2:genmatrix(lambda([i,j], cL2[i+n2]), n2, 1);
matA2B2S:"\\(";
for k:1 thru n2 do matA2B2S:sconcat(matA2B2S, tex1sig(matA2[1, k]), "\\times", tex1sig(matB2[k, 1]), if k<n2 then "+" else "");
matA2B2S:sconcat(matA2B2S, "=");
for k:1 thru n2 do matA2B2S:sconcat(matA2B2S, tex1sig(matA2[1, k]*matB2[k, 1]), if k<n2 then "+" else "");
matA2B2S:sconcat(matA2B2S, "=");
matA2B2S:sconcat(matA2B2S, tex1(matA2.matB2));
matA2B2S:sconcat(matA2B2S, ".\\)");
n3:4;
cL3:random_permutation([-3, -2, -1, -1, 0, 1, 1, 2, 3]);
matA3:genmatrix(lambda([i,j], cL3[j]), 1, n3);
matB3:genmatrix(lambda([i,j], cL3[i+n3]), n3, 1);
matA3B3S:"\\(";
for k:1 thru n3 do matA3B3S:sconcat(matA3B3S, tex1sig(matA3[1, k]), "\\times", tex1sig(matB3[k, 1]), if k<n3 then "+" else "");
matA3B3S:sconcat(matA3B3S, "=");
for k:1 thru n3 do matA3B3S:sconcat(matA3B3S, tex1sig(matA3[1, k]*matB3[k, 1]), if k<n3 then "+" else "");
matA3B3S:sconcat(matA3B3S, "=");
matA3B3S:sconcat(matA3B3S, tex1(matA3.matB3));
matA3B3S:sconcat(matA3B3S, ".\\)");
ta1:matA1.matB1;
ta2:matA2.matB2;
ta3:matA3.matB3;
qtextL:[["en", sconcat("<h2>Product of a Row Vector and a Column Vector</h2>",
 "<p>The product of a row vector and a column vector is obtained by summing the products of the corresponding components, resulting in a single number.</p>",
 "<p>For example, for the row vector ", tex1(matrix([a, b, c])), " and the column vector ", tex1(transpose(matrix([x, y, z]))), ", ",
 "the computation is as follows.</p><p>\\(",
 tex1(matrix([a, b, c])), tex1(transpose(matrix([x, y, z]))),
 "\\(=a \\times x + b \\times y + c \\times z \\)</p>",
 "<p>In this way, by calculating the sum of the products of corresponding components, the product of a row vector and a column vector is a single number.</p>",
 "<p>As a concrete example, for the row vector ", tex1(matA0), " and the column vector ", tex1(matB0), ", the product is</p>",
 "<p style=\"text-align: center;\">", tex1(matA0B0S), "</p><p>.</p>",
 "<p>Now, let’s try some calculations.</p>")],
["fr", sconcat("<h2>Produit d’un vecteur ligne et d’un vecteur colonne</h2>",
 "<p>Le produit d’un vecteur ligne et d’un vecteur colonne s’obtient en additionnant les produits des composantes correspondantes, ce qui donne un seul nombre.</p>",
 "<p>Par exemple, pour le vecteur ligne ", tex1(matrix([a, b, c])), " et le vecteur colonne ", tex1(transpose(matrix([x, y, z]))), ", ",
 "le calcul est le suivant.</p><p>\\(",
 tex1(matrix([a, b, c])), tex1(transpose(matrix([x, y, z]))),
 "\\(=a \\times x + b \\times y + c \\times z \\)</p>",
 "<p>Ainsi, en calculant la somme des produits des composantes correspondantes, le produit d’un vecteur ligne et d’un vecteur colonne est un seul nombre.</p>",
 "<p>Comme exemple concret, pour le vecteur ligne ", tex1(matA0), " et le vecteur colonne ", tex1(matB0), ", le produit est</p>",
 "<p style=\"text-align: center;\">", tex1(matA0B0S), "</p><p>.</p>",
 "<p>Essayons maintenant quelques calculs.</p>")],
["de", sconcat("<h2>Produkt eines Zeilenvektors und eines Spaltenvektors</h2>",
 "<p>Das Produkt eines Zeilenvektors und eines Spaltenvektors erhält man, indem man die Produkte der entsprechenden Komponenten aufsummiert, wodurch eine einzelne Zahl entsteht.</p>",
 "<p>Zum Beispiel für den Zeilenvektor ", tex1(matrix([a, b, c])), " und den Spaltenvektor ", tex1(transpose(matrix([x, y, z]))), " ",
 "ergibt sich die Berechnung wie folgt.</p><p>\\(",
 tex1(matrix([a, b, c])), tex1(transpose(matrix([x, y, z]))),
 "\\(=a \\times x + b \\times y + c \\times z \\)</p>",
 "<p>Auf diese Weise ergibt sich durch die Summe der Produkte entsprechender Komponenten eine einzelne Zahl.</p>",
 "<p>Als konkretes Beispiel ist für den Zeilenvektor ", tex1(matA0), " und den Spaltenvektor ", tex1(matB0), " das Produkt</p>",
 "<p style=\"text-align: center;\">", tex1(matA0B0S), "</p><p>.</p>",
 "<p>Versuchen wir nun einige Berechnungen.</p>")],
 ["ja", sconcat("<h2>行ベクトルと列ベクトルの積</h2>",
 "<p>行ベクトルと列ベクトルの積は, 対応する各要素の積をすべて足し合わせることで求められ, 1つの数値が得られます.</p>",
 "<p>例として、行ベクトル", tex1(matrix([a, b, c])), "と列ベクトル, ", tex1(transpose(matrix([x, y, z]))), "の場合, ",
 "計算は以下のようになります. </p><p>\\(",
 tex1(matrix([a, b, c])), tex1(transpose(matrix([x, y, z]))),
 "\\(=a \\times x + b \\times y + c \\times z \\)</p>",
 "<p>このように, 各要素同士の積の和を計算することで, 行ベクトルと列ベクトルの積は1つの数となります.</p>",
 "<p>具体例として, 行ベクトル", tex1(matA0), "と列ベクトル", tex1(matB0), "の場合, 積は</p>",
 "<p style=\"text-align: center;\">", tex1(matA0B0S), "</p><p>となります.</p>",
 "<p>では, いくつか計算してみましょう.</p>")]];
